import sys

def main():
    data = sys.stdin.read().split()
    x = int(data[0])
    out = []
    for token in data[1:]:
        t = int(token)
        if t > x:
            out.append("menor")
        elif t < x:
            out.append("maior")
        else:
            out.append("correto")
            break
    sys.stdout.write("\n".join(out) + "\n")

main()
